 33	    const scale = new OrdinalScale({
 34	        ordinalMeta: ['a', 'b', 'c', 'd', 'e']
 35	    });
 36	    const axis = new Axis('x', scale, [0, 300]);
 37	    axis.type = 'category';
 38	    axis.onBand = true;
 39	    axis.model = new Model({
 40	        type: 'category',
 41	        axisLabel: {},
 42	        // Display every category.
 43	        axisTick: { show: true, interval: 0 }
 44	    }) as unknown as AxisBaseModel;
 45	    return axis;
 46	}
