import { createChart, getECModel } from '../../core/utHelper';
import { EChartsOption } from '../../../../src/export/option';
import CartesianAxisModel from '../../../../src/coord/cartesian/AxisModel';

function check(axis: any, tag: string, results: string[]) {
    const extent = axis.getExtent();
    const lo = Math.min(extent[0], extent[1]) - 1e-6;
    const hi = Math.max(extent[0], extent[1]) + 1e-6;
    [false, true].forEach(clamp => {
        const tc = axis.getTicksCoords({ clamp: clamp });
        const bad = tc.filter((t: any) => t.coord < lo || t.coord > hi);
        if (bad.length) {
            results.push(`${tag} clamp=${clamp} extent=${extent} all=${JSON.stringify(tc.map((t: any) => t.coord))}`);
        }
    });
}

