describe('zzMyScratchReview', function () {
    it('real-chart dataZoom overflow sweep incl alignWithLabel/boundaryGap/axis types', function () {
        const results: string[] = [];
        const cats: string[] = [];
        const vals: number[] = [];
        for (let i = 0; i < 24; i++) { cats.push('c' + i); vals.push(i % 6 + 1); }
        const windows = [[0, 100], [23, 61], [71, 100], [0, 5], [95, 100], [37.7, 42.1]];
        [true, false].forEach(alignWithLabel => {
            [true, false].forEach(boundaryGap => {
                [true, false].forEach(inverse => {
                    [undefined, 0, 3].forEach(interval => {
                        const chart = createChart({ width: 420, height: 300 });
                        chart.setOption({
                            xAxis: {
                                type: 'category', data: cats, inverse: inverse,
                                boundaryGap: boundaryGap,
                                axisTick: Object.assign(
                                    { alignWithLabel: alignWithLabel },
                                    interval === undefined ? {} : { interval: interval }
                                )
                            },
                            yAxis: {},
                            dataZoom: [{ type: 'inside', start: 0, end: 100 }],
                            series: [{ type: 'bar', data: vals }]
                        } as EChartsOption);
                        windows.forEach(w => {
                            chart.dispatchAction({ type: 'dataZoom', start: w[0], end: w[1] });
                            const axis = (getECModel(chart)
                                .getComponent('xAxis', 0) as CartesianAxisModel).axis;
                            const e = axis.getExtent();
                            const lo = Math.min(e[0], e[1]) - 1e-6;
                            const hi = Math.max(e[0], e[1]) + 1e-6;
                            [false, true].forEach(clamp => {
                                const tc = axis.getTicksCoords({ clamp: clamp });
                                const bad = tc.filter(t => t.coord < lo || t.coord > hi);
                                if (bad.length) {
                                    results.push(`align=${alignWithLabel} bg=${boundaryGap} `
                                        + `inv=${inverse} int=${interval} w=${w} clamp=${clamp} `
                                        + `e=${e} all=${JSON.stringify(tc.map(t => t.coord))}`);
                                }
                            });
                        });
                        chart.dispose();
                    });
                });
            });
        });
        // eslint-disable-next-line
        console.log('MYSWEEP OVERFLOW CASES: ' + results.length);
        results.slice(0, 6).forEach(r => console.log(r));
        expect(true).toBe(true);
    });

